from research_helpers import *
a=ev('https://www.textronsystems.com/products/ground-robotic-vehicles-family-products','Four named RIPSAW platforms; A3 being built and M1 demonstrator not asserted commercially delivered.')
b=ev('https://www.textronsystems.com/products/aerosonde-uas','Two currently offered Mk.4.7 configurations; no invented Mk.4.8.')
c=ev('https://www.textronsystems.com/products/cusv','Separate mine-countermeasures and multi-mission surface-vehicle configurations.')
d=ev('https://www.textronsystems.com/products/tsunami','Five named FLIGHTSHIP vessel variants and three integrated autonomy/engine kit configurations. Mercury propulsion alone not Textron-owned product.')
e=ev('https://www.howeandhowe.com/civil/thermite','Four current named firefighting robots: RS1, RS3, EV1 and EV2.')
f=ev('https://www.howeandhowe.com/civil/swat-bot','Current electric SWAT-BOT EV2 tracked protective robot; source dimension conflicts not copied.')
g=ev('https://www.howeandhowe.com/defense','RS2-H1 named hybrid tracked robotic platform; confirms Howe and Howe part of Textron Systems since 2018.')
h=ev('https://www.textronsystems.com/products/universal-ground-control-station','Current named UGCS robotic aircraft control offering; supported third-party aircraft not attributed as Textron products.')
i=ev('https://www.textronsystems.com/our-company/news-events/articles/press-release/textron-systems-launches-coremotion-robotic-control','October 12 2026 launch of integrated CoreMotion hardware/software robotic control package.')
products=[]
def add(n,desc,src,life='commercial',sub='service_robotics',typ='product'):
 products.append(p(n,desc,src,life,roles=['commercial_partner'],sector='robotics',sub=sub,typ=typ))
for model,life in [('M5','commercial'),('M3','unknown'),('A3','development'),('M1','development')]:add('RIPSAW '+model,'Textron Systems/Howe and Howe uncrewed ground vehicle configuration.',a,life,typ='development_program' if life=='development' else 'product')
for variant in ['Fixed Wing','VTOL']:add('Aerosonde Mk. 4.7 '+variant,'Textron Systems uncrewed aircraft system configuration.',b)
add('CUSV Mine Countermeasures USV','Uncrewed maritime vehicle for mine-countermeasures applications.',c)
add('CUSV Multi-Mission USV','Larger multi-mission uncrewed maritime vehicle configuration.',c,'unknown')
for model in ['21','25','33','38','42']:add('TSUNAMI '+model,'FLIGHTSHIP uncrewed vessel configuration developed with Brunswick.',d)
for model in ['VERADO','MERCRUISER','MERCURY DIESEL']:add('TSUNAMI '+model+' Uncrewed Engine Kit','Integrated propulsion and autonomy conversion kit; not standalone Mercury engine.',d,sub='autonomy_and_components')
for model in ['RS1','RS3','EV1','EV2']:add('Thermite '+model,'Howe and Howe remotely operated firefighting robot.',e)
add('SWAT-BOT EV2','Howe and Howe all-electric tracked mobile protective-shield robot.',f)
add('RS2-H1','Howe and Howe hybrid diesel-electric small tracked robotic vehicle.',g,'unknown')
add('Textron Universal Ground Control Station','UGCS control station for uncrewed aircraft and other robotic assets.',h,sub='autonomy_and_components')
add('CoreMotion','Textron Systems robotic control package combining software and vehicle-interface hardware.',i,sub='autonomy_and_components')
co=dict(company_id='cmp_17a73e7c-20a6-4f31-8e13-c0aacdc4f325',products=products,evidence=[a,b,c,d,e,f,g,h,i],status='partial',coverage_note='Twenty-four distinct robotic platforms, configurations and controls from operating subsidiaries; parent associated as commercial partner. M1/A3 developmental, M3/MMUSV/RS2-H1 delivery status uncertain. Partial: legacy Shadow/Synturian/OSRVT products and additional group autonomy or storage products require review. Third-party aircraft, standalone Brunswick engines and ordinary crewed vehicles not attributed as own robots. Product-family umbrellas not duplicated alongside variants.')
(out/'batch-0293.json').write_text(json.dumps({'companies':[co]},indent=2));print(len(products))
